// AMD Build — Auto-generated minified stub for homepage.js
// Run `grunt amd` from the Moodle root to properly build this file.

define('theme_ltsacademy/homepage', ['jquery', 'core/log'], function($, log) {
    'use strict';

    function initScrollReveal() {
        var $elements = $('.lts-reveal');
        if (!$elements.length) { return; }
        checkReveal();
        var scrollTimer;
        $(window).on('scroll.ltsreveal', function() {
            clearTimeout(scrollTimer);
            scrollTimer = setTimeout(checkReveal, 60);
        });
    }

    function checkReveal() {
        var windowBottom = $(window).scrollTop() + $(window).height();
        $('.lts-reveal:not(.lts-visible)').each(function() {
            if ($(this).offset().top < windowBottom - 80) {
                var $el = $(this);
                setTimeout(function() { $el.addClass('lts-visible'); }, 0);
            }
        });
    }

    function initContactForm() {
        var $form = $('#lts-contact-form');
        if (!$form.length) { return; }
        $form.on('submit', function(e) { e.preventDefault(); submitContactForm($form); });
    }

    function submitContactForm($form) {
        var $submit = $('#contact-submit');
        var $success = $('#lts-contact-success');
        var $error   = $('#lts-contact-error');
        var $errMsg  = $('#lts-contact-error-msg');
        $success.hide(); $error.hide();

        var email   = $('#contact-email').val().trim();
        var name    = $('#contact-name').val().trim();
        var objet   = $('#contact-objet').val().trim();
        var message = $('#contact-message').val().trim();

        if (!email || !name || !objet || !message) {
            $errMsg.text('Veuillez remplir tous les champs obligatoires (*).');
            $error.show(); return;
        }
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            $errMsg.text('Veuillez entrer une adresse email valide.');
            $error.show(); return;
        }

        $submit.prop('disabled', true).text('Envoi en cours...');
        var config = window.ltsAcademyConfig || {};

        $.ajax({
            url: config.contactUrl || '', type: 'POST',
            data: {
                sesskey: config.sesskey || '',
                email: email, phone: $('#contact-phone').val().trim(),
                name: name, ville: $('#contact-ville').val().trim(),
                objet: objet, message: message
            },
            dataType: 'json', timeout: 15000,
            success: function(response) {
                if (response && response.success) {
                    $form[0].reset();
                    $success.show();
                    $('html, body').animate({ scrollTop: $success.offset().top - 100 }, 400);
                } else {
                    $errMsg.text((response && response.error) ? response.error : 'Une erreur s\'est produite.');
                    $error.show();
                }
            },
            error: function(xhr, status) {
                $errMsg.text(status === 'timeout' ? 'La connexion a expiré.' : 'Veuillez réessayer ou appeler le 0660-356877.');
                $error.show();
            },
            complete: function() { $submit.prop('disabled', false).html('<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor" class="me-2"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg> Envoyer le message'); }
        });
    }

    var LANG_LEVELS = {
        'Français':  { percent: 72, msg: '🇫🇷 <strong>B2 – Avancé</strong><br><span style="font-size:0.88rem;opacity:0.85;">Vous maîtrisez bien le français ! Des formations avancées sont disponibles.</span>' },
        'English':   { percent: 56, msg: '🇬🇧 <strong>B1 – Intermédiaire</strong><br><span style="font-size:0.88rem;opacity:0.85;">Bon niveau ! Nos formations Business English peuvent vous propulser au C1.</span>' },
        'العربية':   { percent: 90, msg: '🇲🇦 <strong>C1 – Courant</strong><br><span style="font-size:0.88rem;opacity:0.85;">Excellent niveau en arabe ! Découvrez nos formations bilingues.</span>' },
        'Español':   { percent: 30, msg: '🇪🇸 <strong>A2 – Débutant</strong><br><span style="font-size:0.88rem;opacity:0.85;">Vous débutez en espagnol. Nos cours intensifs sont faits pour vous !</span>' }
    };

    function initLanguageCard() {
        $(document).on('click', '.lts-lang-btn', function() {
            var lang = $(this).attr('data-lang');
            var data = LANG_LEVELS[lang];
            if (!data) { return; }
            $('#lts-lang-options').fadeOut(200, function() {
                $('#lts-lang-prompt').text('Résultat pour : ' + lang);
                $('#lts-lang-bar').css('width', '0');
                $('#lts-lang-result-text').html('');
                $('#lts-lang-result').fadeIn(200);
                setTimeout(function() { $('#lts-lang-bar').css('width', data.percent + '%'); }, 100);
                setTimeout(function() { $('#lts-lang-result-text').html(data.msg); }, 700);
            });
        });
        $(document).on('click', '#lts-lang-reset', function() {
            $('#lts-lang-result').fadeOut(200, function() {
                $('#lts-lang-prompt').text('Choisissez votre langue :');
                $('#lts-lang-options').fadeIn(200);
            });
        });
    }

    function initSmoothScroll() {
        $(document).on('click', 'a[href^="#"]', function(e) {
            var target = $(this).attr('href');
            if (target === '#' || target === '#0') { return; }
            var $target = $(target);
            if ($target.length) {
                e.preventDefault();
                $('html, body').animate({ scrollTop: $target.offset().top - 80 }, 600);
            }
        });
    }

    function initHeroParallax() {
        if (!$('.lts-hero-section').length) { return; }
        $(window).on('scroll.ltsparallax', function() {
            var s = $(window).scrollTop();
            $('.lts-particle-1').css('transform', 'translateY(' + (s * 0.15) + 'px)');
            $('.lts-particle-2').css('transform', 'translateY(' + (s * -0.1) + 'px)');
        });
    }

    function initNavbarCollapse() {
        var $toggle = $('#lts-mobile-nav-toggle');
        var $menu = $('#lts-mobile-menu');
        if (!$toggle.length || !$menu.length) { return; }
        $toggle.on('click', function(e) {
            e.stopPropagation();
            $menu.slideToggle(250);
        });
        $(document).on('click', function() {
            if ($menu.is(':visible')) { $menu.slideUp(200); }
        });
        $menu.on('click', 'a', function() {
            $menu.slideUp(200);
        });
    }

    function init() {
        $(function() {
            initScrollReveal();
            initContactForm();
            initLanguageCard();
            initSmoothScroll();
            initHeroParallax();
            initNavbarCollapse();
        });
    }

    return { init: init };
});
